mapper.select:
SELECT area.id, area.name, area.description, area.active, COUNT(inspection.id) AS inspection_count, MAX(inspection.created_at) AS last_inspected_at, EXISTS ( SELECT 1 FROM checklist_templates template WHERE template.inspection_area_id = area.id AND template.status = 'ACTIVE' ) AS has_active_template FROM inspection_areas area LEFT JOIN safety_inspections inspection ON inspection.inspection_area_id = area.id
AND inspection.inspector_id = #{inspectorId}
WHERE area.active = TRUE GROUP BY area.id, area.name, area.description, area.active, area.created_at ORDER BY area.created_at DESC, area.id DESC

SELECT area.id, area.name, area.description, area.active, COUNT(inspection.id) AS inspection_count, MAX(inspection.created_at) AS last_inspected_at, EXISTS ( SELECT 1 FROM checklist_templates template WHERE template.inspection_area_id = area.id AND template.status = 'ACTIVE' ) AS has_active_template FROM inspection_areas area LEFT JOIN safety_inspections inspection ON inspection.inspection_area_id = area.id
AND inspection.inspector_id = #{inspectorId}
WHERE area.id = #{areaId} GROUP BY area.id, area.name, area.description, area.active

mapper.update:
UPDATE inspection_areas
SET name = #{name},
    description = #{description}
WHERE id = #{id}
  AND active = TRUE

mapper.select:
SELECT inspection.id, inspection.inspector_id, inspection.status, COALESCE(SUM(item.result != 'PENDING'), 0) AS completed_item_count, COUNT(item.id) AS total_item_count, COALESCE(SUM(item.result = 'FAIL'), 0) AS fail_count, COALESCE(SUM(item.result = 'REVIEW_REQUIRED'), 0) AS review_required_count, inspection.created_at FROM safety_inspections inspection LEFT JOIN safety_inspection_items item ON item.safety_inspection_id = inspection.id WHERE inspection.inspection_area_id = #{areaId}
AND inspection.inspector_id = #{inspectorId}
GROUP BY inspection.id, inspection.inspector_id, inspection.status, inspection.created_at ORDER BY inspection.created_at DESC, inspection.id DESC

SELECT version
FROM checklist_templates
WHERE id = #{templateId}

SELECT COALESCE(MAX(version), 0) + 1
FROM checklist_templates
WHERE inspection_area_id = #{areaId}

mapper.update:
UPDATE safety_inspection_items item
JOIN safety_inspections inspection
  ON inspection.id = item.safety_inspection_id
SET item.result = #{result},
    item.comment = #{comment},
    item.checked_at = #{checkedAt}
WHERE item.id = #{itemId}
  AND item.safety_inspection_id = #{inspectionId}
  AND inspection.status = 'DRAFT'

mapper.select:
SELECT COUNT(*)
FROM safety_inspection_items
WHERE safety_inspection_id = #{inspectionId}

mapper.update:
UPDATE safety_inspections
SET status = #{status},
    comment = #{comment},
    completed_at = #{completedAt}
WHERE id = #{inspectionId}
  AND status = 'DRAFT'

mapper.delete:
DELETE FROM safety_inspections
WHERE id = #{inspectionId}
  AND status = 'DRAFT'
